SELECT COUNT(1) FROM public.iam_role
WHERE tenant_id = #{tenantId} AND organization_id = #{organizationId} AND is_deleted = false
AND status = #{status}

SELECT 
FROM public.iam_role role
WHERE role.tenant_id = #{tenantId} AND role.organization_id = #{organizationId}
  AND role.is_deleted = false
AND role.status = #{status}
ORDER BY CASE WHEN role.role_type = 'OWNER' THEN 0 ELSE 1 END, role.name, role.id
OFFSET #{offset} LIMIT #{limit}

