INSERT INTO public.iam_role (
    id, tenant_id, organization_id, role_code, name, normalized_name, description,
    role_type, status, authz_version, created_by, updated_by
) VALUES (
    #{id}, #{tenantId}, #{organizationId}, #{roleCode}, #{name}, #{normalizedName}, #{description},
    #{roleType}, #{status}, 0, #{createdBy}, #{updatedBy}
)

INSERT INTO public.iam_role_data_policy (
    id, tenant_id, organization_id, role_id, module_code, scope_type, created_by, updated_by
) VALUES (
    #{policyId}, #{tenantId}, #{organizationId}, #{roleId}, #{moduleCode}, #{scopeType},
    #{operatorId}, #{operatorId}
