mapper.update:
UPDATE public.iam_role
SET status = #{status}, authz_version = authz_version + 1,
    updated_by = #{operatorId}, updated_time = CURRENT_TIMESTAMP, version = version + 1
WHERE tenant_id = #{tenantId} AND organization_id = #{organizationId} AND id = #{roleId}
  AND role_type = 'CUSTOM' AND status <> #{status}
  AND version = #{version} AND is_deleted = false

