SELECT COUNT(DISTINCT organization.id) FROM public.iam_organization organization JOIN public.iam_organization_closure path ON path.tenant_id = organization.tenant_id AND path.descendant_id = organization.id AND path.ancestor_id = #{actorOrganizationId} AND path.is_deleted = false WHERE organization.tenant_id = #{tenantId} AND organization.id IN
#{organizationId}
AND organization.is_deleted = false
